import * as THREE from 'three';
import { Reflector } from 'three/addons/objects/Reflector.js';
import { detachWaterOptics } from './waterOptics';

export interface WaterRenderInputs {
  meshes: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>[];
  seaMaterial: THREE.ShaderMaterial;
  quality: 'low' | 'medium' | 'high';
  enabled: boolean;
  reducedMotion: boolean;
  /** Renderer work the water needs before every frame (its sky capture and ripple solve), on every quality. */
  prepare?: (renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera, dt: number) => void;
  /** With the camera under water: how far above the eye the surface stands, and the water's colour and absorption. */
  under?: WaterUnder | null;
  /** Drawn in the water pass after the water itself (its spray), so the surface never paints over them (A70). */
  overlays?: THREE.Object3D[];
  /**
   * Left out of the planar reflection (A76): the grass and the forest floor's plants, a third of what the reflection
   * drew, are lost in a 512 px image of a rippled surface; the land, trees, buildings and figures stay in it.
   */
  unreflected?: THREE.Object3D[];
  /** Lighten what the reflection draws (the trees' middle models, A76); returns how to put it back. */
  lighten?: () => () => void;
}

export interface WaterUnder {
  /** Metres from the eye up to the surface. */
  surface: number;
  /** Light the water scatters toward the eye (linear) and its absorption per metre. */
  color: THREE.Color;
  absorb: THREE.Vector3;
  /** The caustic web thrown on the bed, and how much sunlight there is to throw it (0 at night). */
  caustics: THREE.Texture | null;
  light: number;
}

/** A single mesh smaller than this (pixels of radius in the reflection image) is left out of the reflection (A78). */
export const REFLECTION_DETAIL_PX = 1.5;

