  }

  /** Conservative world-space boxes retain wave crests and changing channel levels at screen edges. */
  private waterInView(mesh: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>, camera: THREE.Camera): boolean {
    if (!camera.layers.test(mesh.layers) || !mesh.material.visible) return false;
    for (let parent: THREE.Object3D | null = mesh; parent; parent = parent.parent) if (!parent.visible) return false;
    mesh.updateWorldMatrix(true, false);
    if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
    // Sea's complete welded geometry includes dry inland triangles which its shader discards.
    // Its cached depth-derived envelope excludes only those impossible pixels; channels keep
    // their existing bounds, including every hydraulic level.
    // Sea relief is bounded below 0.72 m; inland bounds already include all hydraulic levels and ripples.
    // A full metre in local space deliberately overestimates both so visibility never clips an animated crest.
    const pieces = mesh.userData.waterVisibilityBounds as THREE.Box3[] | undefined;
    if (pieces) return pieces.some(bounds => {
      this.visibilityBox.copy(bounds).expandByScalar(1).applyMatrix4(mesh.matrixWorld);
      return this.visibilityFrustum.intersectsBox(this.visibilityBox);
    });
    const bounds = mesh.geometry.boundingBox;
    if (!bounds || bounds.isEmpty()) return false;
    this.visibilityBox.copy(bounds).expandByScalar(1).applyMatrix4(mesh.matrixWorld);
    return this.visibilityFrustum.intersectsBox(this.visibilityBox);
  }

  /**
   * Hide, for the reflection only, single meshes that would cover less than REFLECTION_DETAIL_PX pixels of radius in the
   * reflection image as seen from the mirrored eye (A78): doors, props, tools and stones far up the shore. In a rippled
   * 512 px reflection they are sub-pixel specks, yet each cost a draw call; the land, trees, buildings and near figures
   * stay. Meshes wholly below the water plane (the sea floor's ground) are hidden too: the reflection clips them away,
   * but its culling does not know the plane. Returns what was hidden, to show again once the reflection is drawn.
   */
  /**
   * Every few seconds: gather the scene's single meshes (for hideTinyDetail), and put every light on the water's layer
   * too (A78). The water's own pass draws layer 1 alone; with the lights only on layer 0 it saw none, three took that
   * as a change of lighting, and on the next pass re-resolved the shader program of every lit material (about 130
   * lookups a frame). Lights on both layers light exactly what they did; only the lighting state stays the same.
   */
  private gather(scene: THREE.Scene, dt: number) {
    this.detailAge += Number.isFinite(dt) && dt > 0 ? dt : 0;
    if (this.detailScene === scene && this.detailAge <= 2) return;
    this.detail = [];
    scene.traverse((object) => {
      if ((object as THREE.Light).isLight) { object.layers.enable(1); return; }
      const mesh = object as THREE.Mesh;
      if (mesh.isMesh && mesh.visible && !(mesh as THREE.InstancedMesh).isInstancedMesh && !(mesh as THREE.BatchedMesh).isBatchedMesh && mesh.frustumCulled) this.detail.push(mesh);
    });
    this.detailScene = scene; this.detailAge = 0;
  }

  private hideTinyDetail(camera: THREE.Camera, size: number): THREE.Object3D[] {
    const perspective = camera as THREE.PerspectiveCamera;
    if (!perspective.isPerspectiveCamera) return [];
    // The reflection camera stands at the eye mirrored in the water plane; its picture has the main view's field.
    const plane = this.reflector!.getWorldPosition(this.mirroredEye).y;
    this.mirroredEye.copy(this.currentCameraPosition); this.mirroredEye.y = 2 * plane - this.mirroredEye.y;
    const pixelsPerRadian = size / 2 / Math.tan(THREE.MathUtils.degToRad(perspective.fov) / 2);
    const hidden: THREE.Object3D[] = [];
    for (const mesh of this.detail) {
      if (!mesh.visible || !mesh.parent) continue;
      const geometry = mesh.geometry;
      if (!geometry.boundingSphere) geometry.computeBoundingSphere();
      const sphere = this.detailBounds.sphere(geometry.boundingSphere!, mesh.matrixWorld);
      const distance = sphere.center.distanceTo(this.mirroredEye) - sphere.radius;
      let hide = distance > 0 && sphere.radius / distance * pixelsPerRadian < REFLECTION_DETAIL_PX;
      if (!hide && sphere.center.y - sphere.radius < plane) {
        if (!geometry.boundingBox) geometry.computeBoundingBox();
        hide = this.detailBounds.box(geometry.boundingBox!, mesh.matrixWorld).max.y < plane - 0.01;
      }
      if (hide) { mesh.visible = false; hidden.push(mesh); }
    }
    return hidden;
  }

  private captureReflection(renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera,
    source: THREE.WebGLRenderTarget, dt: number, input: WaterRenderInputs) {
    const u = input.seaMaterial.uniforms;
    u.uWaterReflectionReady!.value = 0;
    // Only visible sea needs a planar capture; a map longitude is not a visibility boundary.
    camera.getWorldPosition(this.currentCameraPosition);
    camera.getWorldQuaternion(this.currentCameraRotation);
    if (WaterRenderPass.captureOff || this.currentCameraPosition.y <= 0.08 || !input.meshes.some(m => m.name === 'sea' && this.waterInView(m, camera))) return;
    if (this.reflectionScene !== scene) { this.reflectionValid = false; this.reflectionScene = scene; }
    const size = input.quality === 'high' ? 512 : 384;
    if (this.reflector && this.reflector.getRenderTarget().texture.type !== source.texture.type) {
      this.reflector.dispose(); this.reflector.geometry.dispose(); this.reflector = null;
      this.reflectionValid = false;
    }
    if (!this.reflector) {
      this.reflector = new Reflector(new THREE.PlaneGeometry(1, 1), { textureWidth: size, textureHeight: size, multisample: 0, clipBias: 0.002 });
      this.reflector.rotation.x = -Math.PI / 2;
      this.reflector.updateMatrixWorld(true);
      this.reflector.getRenderTarget().texture.type = source.texture.type;
      // Capture mip levels prefilter distant stone/trees without another scene
      // pass. The water shader supplies valid gradients even at discarded shores.
      const texture = this.reflector.getRenderTarget().texture;
      texture.colorSpace = THREE.LinearSRGBColorSpace;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      texture.generateMipmaps = true;
    }
    const target = this.reflector.getRenderTarget();
    if (target.width !== size) { target.setSize(size, size); this.reflectionValid = false; }
    if (Number.isFinite(dt) && dt > 0) this.reflectionAge += dt;
    // A cached reflection is a view-dependent image. During walking, running,
    // orbiting or zooming it must follow every rendered camera pose; throttling
    // it here makes reflected shorelines jump by 0.39–0.59 m at running speed.
    // Only numerical camera noise is ignored, not ordinary slow movement.
    const moved = this.reflectionCameraPosition.distanceToSquared(this.currentCameraPosition) > 1e-8
      || this.reflectionCameraRotation.angleTo(this.currentCameraRotation) > 1e-5
      || !this.reflectionProjection.equals(camera.projectionMatrix);
    const sun = Number(u.uSunI?.value ?? 0), night = Number(u.uNight?.value ?? 0);
    const lightingChanged = Math.abs(this.reflectionLight.x - sun) > 0.025 || Math.abs(this.reflectionLight.y - night) > 0.02;
    const interval = input.quality === 'high' ? 1 / 15 : 1 / 10;
    // Stationary scene animation keeps the bounded refresh cadence, including
    // a frozen valid image for Reduced Motion. Camera movement never waits.
    if (!this.reflectionValid || moved || this.reflectionAge >= interval && (lightingChanged || !input.reducedMotion)) {
      const visible = this.reflectionVisible; visible.length = input.meshes.length;
      for (let i = 0; i < input.meshes.length; i++) visible[i] = input.meshes[i]!.visible;
      const unreflected = input.unreflected ?? [], shown = this.reflectionShown; shown.length = unreflected.length;
      for (let i = 0; i < unreflected.length; i++) shown[i] = unreflected[i]!.visible;
      let restoreDetail: (() => void) | null = null, hiddenDetail: THREE.Object3D[] = [];
      const oldTarget = renderer.getRenderTarget(), oldAutoClear = renderer.autoClear;
      const oldShadow = renderer.shadowMap.autoUpdate, oldXr = renderer.xr.enabled;
      try {
        for (const mesh of input.meshes) mesh.visible = false;
        for (const object of unreflected) object.visible = false;
        restoreDetail = input.lighten?.() ?? null;
        hiddenDetail = this.hideTinyDetail(camera, size);
        renderer.autoClear = true;
        this.reflectionValid = false;
        this.reflector.getReflectionCamera(camera).layers.mask = camera.layers.mask & ~2;
        this.reflector.onBeforeRender(renderer, scene, camera, this.reflector.geometry, this.reflector.material as THREE.Material, this.reflectionGroup);
        this.reflectionValid = true; this.reflectionAge = 0;
        this.reflectionCameraPosition.copy(this.currentCameraPosition);
        this.reflectionCameraRotation.copy(this.currentCameraRotation);
        this.reflectionProjection.copy(camera.projectionMatrix);
        this.reflectionLight.set(sun, night);
      } finally {
        input.meshes.forEach((mesh, i) => { mesh.visible = visible[i]!; });
        unreflected.forEach((object, i) => { object.visible = shown[i]!; });
        restoreDetail?.();
        for (const object of hiddenDetail) object.visible = true;
        renderer.autoClear = oldAutoClear; renderer.shadowMap.autoUpdate = oldShadow; renderer.xr.enabled = oldXr;
        renderer.setRenderTarget(oldTarget);
      }
    }
    if (this.reflectionValid) {
      u.tWaterReflection!.value = target.texture;
      // Reflector's matrix maps local plane space; our shader supplies world coordinates.
      u.uWaterReflectionMatrix!.value.copy((this.reflector.material as THREE.ShaderMaterial).uniforms.textureMatrix!.value)
        .multiply(this.inverseReflectionWorld.copy(this.reflector.matrixWorld).invert());
      // Approaching the mean sea plane fades to sky instead of flipping the
      // reflected coastline on/off at the planar camera's safe clipping height.
      u.uWaterReflectionReady!.value = THREE.MathUtils.smoothstep(this.currentCameraPosition.y, 0.08, 0.35);
    }
  }

  render(renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera,
    source: THREE.WebGLRenderTarget, dt: number, input: WaterRenderInputs): THREE.Texture {
    if (this.disposed) throw new Error('WaterRenderPass has been disposed');
    input.prepare?.(renderer, scene, camera, dt);
    if (!input.enabled || input.quality === 'low' || !source.depthTexture) {
      input.meshes.forEach(mesh => detachWaterOptics(mesh.material));
      this.releaseTargets();
      const previous = renderer.getRenderTarget(), previousAutoClear = renderer.autoClear;
      try { renderer.autoClear = true; renderer.setRenderTarget(source); renderer.render(scene, camera); }
      finally { renderer.autoClear = previousAutoClear; renderer.setRenderTarget(previous); }
      return source.texture;
    }
    camera.updateWorldMatrix(true, false);
    this.visibilityProjection.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    this.visibilityFrustum.setFromProjectionMatrix(this.visibilityProjection);
    if (!input.meshes.some(mesh => this.waterInView(mesh, camera))) {
      // Looking inland needs one scene render, with no full-resolution copy or second water traversal. Retain
      // private targets for turning back toward the shore rather than reallocating them at every visibility change.
      input.meshes.forEach(mesh => detachWaterOptics(mesh.material));
      if (Number.isFinite(dt) && dt > 0) this.reflectionAge += dt;
      const previous = renderer.getRenderTarget(), previousAutoClear = renderer.autoClear;
      try { renderer.autoClear = true; renderer.setRenderTarget(source); renderer.render(scene, camera); }
      finally { renderer.autoClear = previousAutoClear; renderer.setRenderTarget(previous); }
      return source.texture;
    }
    this.prepare(source);
    this.gather(scene, dt);
    const oldTarget = renderer.getRenderTarget(), oldAutoClear = renderer.autoClear;
    const oldMask = camera.layers.mask, meshMasks = this.meshMasks; meshMasks.length = input.meshes.length;
    for (let i = 0; i < input.meshes.length; i++) meshMasks[i] = input.meshes[i]!.layers.mask;
    const overlays = input.overlays ?? [], overlayMasks = this.overlayMasks; overlayMasks.length = overlays.length;
    for (let i = 0; i < overlays.length; i++) overlayMasks[i] = overlays[i]!.layers.mask;
    try {
      camera.updateMatrixWorld();
      this.captureReflection(renderer, scene, camera, source, dt, input);
      input.meshes.forEach((mesh, i) => { mesh.layers.mask = (oldMask & meshMasks[i]!) !== 0 ? 2 : 0; });
      overlays.forEach((o, i) => { o.layers.mask = (oldMask & overlayMasks[i]!) !== 0 ? 2 : 0; });
      camera.layers.mask = oldMask & ~2;
      renderer.autoClear = true;
      renderer.setRenderTarget(source); renderer.render(scene, camera);
      renderer.setRenderTarget(this.composite); renderer.render(this.copyScene, this.copyCamera);
      for (const mesh of input.meshes) {
        const u = mesh.material.uniforms;
        u.tWaterColor!.value = source.texture; u.tWaterDepth!.value = source.depthTexture;
        u.uWaterResolution!.value.set(source.width, source.height);
        const pc = camera as THREE.PerspectiveCamera;
        u.uWaterNear!.value = pc.near; u.uWaterFar!.value = pc.far;
        u.uWaterInverseProjection?.value.copy(camera.projectionMatrixInverse);
        u.uWaterCameraWorld?.value.copy(camera.matrixWorld);
        u.uWaterCapture!.value = 1;
      }
      // The copied opaque depth still hides water behind rocks, boats and people.
      // The sun's shadow was drawn by the main pass: redrawn here for the water layer alone, it was cleared and left empty
      // for the frame's later captures, at the cost of a second shadow pass every frame (A103 scout).
      const oldShadow = renderer.shadowMap.autoUpdate;
      renderer.autoClear = false; camera.layers.set(1); renderer.shadowMap.autoUpdate = false;
      try { renderer.render(scene, camera); } finally { renderer.shadowMap.autoUpdate = oldShadow; }
      return this.composite!.texture;
    } catch (error) {
      input.meshes.forEach(mesh => detachWaterOptics(mesh.material));
      throw error;
    } finally {
      camera.layers.mask = oldMask;
      input.meshes.forEach((mesh, i) => { mesh.layers.mask = meshMasks[i]!; });
      overlays.forEach((o, i) => { o.layers.mask = overlayMasks[i]!; });
      renderer.autoClear = oldAutoClear; renderer.setRenderTarget(oldTarget);
    }
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true; this.releaseTargets();
    this.copyMaterial.dispose(); this.quad.geometry.dispose();
  }
}

